const imgs=[...document.querySelectorAll('img')].filter(i=>i.src.includes('profile-displayphoto') || i.src.includes('profile-framedphoto'));
const top=imgs.map(i=>({i, r:i.getBoundingClientRect()})).filter(o=>o.r.top<400 && o.r.width>80);
const el=top[0]?.i;
const blob=await (await fetch(el.currentSrc||el.src)).blob();
const b64=await new Promise(r=>{const fr=new FileReader(); fr.onload=()=>r(fr.result.split(',')[1]); fr.readAsDataURL(blob);});
window.__photo=b64;
({count:top.length, w:el.naturalWidth, h:el.naturalHeight, rect:[top[0].r.left,top[0].r.top,top[0].r.width], type:blob.type, size:blob.size, srcsetSizes:(el.srcset||'').split(',').map(s=>s.trim().split(' ').pop())})

const bin=atob(window.__photo); const u=new Uint8Array(bin.length); for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
const bmp=await createImageBitmap(new Blob([u],{type:'image/png'}));
const c=document.createElement('canvas'); c.width=c.height=100; const x=c.getContext('2d'); x.imageSmoothingQuality='high';
const s=Math.min(bmp.width,bmp.height); x.drawImage(bmp,(bmp.width-s)/2,(bmp.height-s)/2,s,s,0,0,100,100);
c.toDataURL('image/jpeg',0.9).split(',')[1]

